from unittest import mock
from pathlib import Path
import builtins

import pylint.lint.run as run

files = {
    "/sys/fs/cgroup/cpu/cpu.cfs_quota_us": "-1\n",
    "/sys/fs/cgroup/cpu/cpu.cfs_period_us": "100000\n",
    "/sys/fs/cgroup/cpu/cpu.shares": "2\n",
}

real_open = builtins.open

def fake_is_file(self: Path):
    return str(self) in files

def fake_open(path, *args, **kwargs):
    p = str(path)
    if p in files:
        return mock.mock_open(read_data=files[p])()
    return real_open(path, *args, **kwargs)

with mock.patch.object(Path, "is_file", fake_is_file), mock.patch.object(builtins, "open", fake_open):
    print("query_cpu:", run._query_cpu())
    print("cpu_count:", run._cpu_count())
